import 'package:global_configs/global_configs.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  GlobalConfigs().loadFromMap({
    'appearance': {'defaultTheme': 'Dark'}
  });
  var theme = GlobalConfigs().get<String>('appearance.defaultTheme');
  print(theme); // Dark
}
